function generate(info) {
  /*
  ** info Object组件自带参数
  * @params id: 组件id
  * @params list: 绑定数据
  * @params emitEvent: 通信函数,固定交互通信函数名为fireCustomCode_${组件id}，或fireCustomCode_${配置自定义函数名}
  * @params defaultFun: 内置的函数 如:深拷贝cloneDeep, 防抖debounce, 节流throttle
  */
  const { id, list, emitEvent, defaultFun } = info || {};
  const { cloneDeep } = defaultFun || {};
  return {
    name: 'customCode',
    inject: ['main'],
    data() {
      return {
        dataList: list,
        message: 'vue2 片段'
      }
    },
    watch: {},
    computed: {},
    created() {},
    mounted() {},
    methods: {
      // 系统自带交互方法
      onClick(item) {
        if (id && emitEvent) {
          emitEvent(`fireCustomCode_${id}`, item);
        }
      }
    },
  }
}

